import { randomBytes } from 'node:crypto';

// Object keys are generated by the server only. They never contain user input.
export const SAFE_KEY = /^(?!.*\.\.)[a-z0-9][a-z0-9/_.-]{0,250}$/;

/** Sortable, unguessable id: base36 time + 12 random hex chars. */
export function newObjectId(now = Date.now()) {
  return `${now.toString(36)}${randomBytes(6).toString('hex')}`;
}

export function assertSafeKey(key) {
  if (typeof key !== 'string' || !SAFE_KEY.test(key)) throw new Error(`Unsafe storage key: ${key}`);
  return key;
}

/** products/42/lx3k9f2a1b2c3d4e5f6 */
export const productImageKey = (productId) => `products/${productId}/${newObjectId()}`;

/** sellers/7/docs/lx3k9f2a1b2c3d4e5f6.pdf */
export const sellerDocumentKey = (sellerId, ext) => `sellers/${sellerId}/docs/${newObjectId()}.${ext}`;
